# Alignment Commons taxonomy: Area > Subfield > Topic.
# kw: regex fragments matched case-insensitively against title (x3) and summary/abstract (x1).
# sr: Shallow Review 2025 classifier category ids that signal this node.

def T(id, name, desc, kw=(), sr=()):
    return dict(id=id, name=name, desc=desc, kw=list(kw), sr=list(sr))

def S(id, name, desc, topics, kw=(), sr=()):
    return dict(id=id, name=name, desc=desc, topics=topics, kw=list(kw), sr=list(sr))

def A(id, name, desc, subs, color):
    return dict(id=id, name=name, desc=desc, subs=subs, color=color)

